sys_script_include.script:
var InsuranceUtils = Class.create();
InsuranceUtils.prototype = {
    initialize: function() {
		this.source = new GlideRecord('u_insurance');
    },

	fetchInsuranceDetailsByPatientId : function(patId){
		this.source.addQuery('u_patient_id', patId);
		this.source.query();
		return this.source;
	},

	checkIfExpired : function(insId){
		this.source.get(insId);
		return this.source.u_status == 'expired';
	},

	fetchPolicyById : function(insId){
		this.source.get(insId);
		var result = {
			ins_num : this.source.getValue('number'),
			ins_pat_id : this.source.getValue('u_patient_id'),
			ins_app_id : this.source.getValue('u_appointment_id'),
			ins_pol_num : this.source.getValue('u_policy_number'),
			ins_cov_det : this.source.getValue('u_coverage_details'),
			ins_stat : this.source.getValue('u_status'),
		};
		return results;
	},

	fetchInsurancePolicyByProvider : function(providerName){
		this.source.addQuery('u_provider', providerName);
		this.source.query();
		return this.source;
	},
    type: 'InsuranceUtils'
};
